from typing import List

class Solution:
    def countNonDecreasingSubarrays(self, nums: List[int], k: int) -> int:
        n = len(nums)
        ans = 0
        for start in range(n):
            mx = nums[start]      # maximum element seen so far in the subarray
            ops = 0               # operations needed for current subarray
            # subarray of length 1 always needs 0 operations
            ans += 1
            for end in range(start + 1, n):
                if nums[end] < mx:
                    ops += mx - nums[end]
                mx = max(mx, nums[end])
                if ops <= k:
                    ans += 1
        return ans

