class Solution:
    def maximumAmount(self, coins: List[List[int]]) -> int:
        m = len(coins)
        n = len(coins[0])
        INF_NEG = -10 ** 18

        # dp[i][j][k] : max profit at (i,j) using k neutralisations (k = 0..2)
        dp = [[[INF_NEG] * 3 for _ in range(n)] for _ in range(m)]

        # initialise start cell
        for k in range(3):
            dp[0][0][k] = coins[0][0]

        for i in range(m):
            for j in range(n):
                for used in range(3):
                    cur = dp[i][j][used]
                    if cur == INF_NEG:
                        continue
                    # move down
                    if i + 1 < m:
                        # without neutralising
                        nxt = cur + coins[i + 1][j]
                        if nxt > dp[i + 1][j][used]:
                            dp[i + 1][j][used] = nxt
                        # with neutralising
                        if used < 2:
                            if cur > dp[i + 1][j][used + 1]:
                                dp[i + 1][j][used + 1] = cur
                    # move right
                    if j + 1 < n:
                        nxt = cur + coins[i][j + 1]
                        if nxt > dp[i][j + 1][used]:
                            dp[i][j + 1][used] = nxt
                        if used < 2:
                            if cur > dp[i][j + 1][used + 1]:
                                dp[i][j + 1][used + 1] = cur

        return max(dp[m - 1][n - 1])

