class Solution:
    def shortestMatchingSubstring(self, s: str, p: str) -> int:
        # compile the regular expression that corresponds to the pattern
        # '*' -> '.*' (any characters, any length)
        regex = '^' + p.replace('*', '.*') + '$'
        pattern = re.compile(regex)

        n = len(s)
        # try lengths from 0 (empty substring) up to n
        for length in range(n + 1):
            for start in range(n - length + 1):
                sub = s[start:start + length]
                if pattern.fullmatch(sub):
                    return length
        return -1

