        # enumerate all substrings
        for i in range(n):
            cur = 0
            for j in range(i, n):
                # build the integer value of s[i..j]
                cur = cur * 10 + (ord(s[j]) - ord('0'))
                d = ord(s[j]) - ord('0')
                if d != 0 and cur % d == 0:
                    ans += 1
        return ans

