class Solution:
    def hasSpecialSubstring(self, s: str, k: int) -> bool:
        n = len(s)
        if k > n:
            return False

        for i in range(n - k + 1):
            # character that would repeat in the substring
            ch = s[i]

            # 1) substring must consist of the same character
            #   we can stop early if any character differs
            all_same = True
            for j in range(i, i + k):
                if s[j] != ch:
                    all_same = False
                    break
            if not all_same:
                continue

            # 2) preceding character (if any) must be different
            if i > 0 and s[i - 1] == ch:
                continue

            # 3) following character (if any) must be different
            if i + k < n and s[i + k] == ch:
                continue

            # all conditions satisfied
            return True

        return False

