class Solution:
    def countMentions(self, numberOfUsers: int, events: List[List[str]]) -> List[int]:
        mentions = [0] * numberOfUsers
        online = [True] * numberOfUsers               # everybody online initially
        offline_until = [-1] * numberOfUsers          # -1 means "not offline"

        # sort: timestamp asc, OFFLINE before MESSAGE
        events_sorted = sorted(events,
                               key=lambda e: (int(e[1]), 0 if e[0] == "OFFLINE" else 1))

        for ev in events_sorted:
            t = int(ev[1])

            # bring back users whose offline period finished at or before t
            for uid in range(numberOfUsers):
                if not online[uid] and offline_until[uid] <= t:
                    online[uid] = True
                    offline_until[uid] = -1

            if ev[0] == "OFFLINE":
                uid = int(ev[2])
                online[uid] = False
                offline_until[uid] = t + 60
            else:   # MESSAGE
                tokens = ev[2].split()
                for token in tokens:
                    if token == "ALL":
                        for uid in range(numberOfUsers):
                            mentions[uid] += 1
                    elif token == "HERE":
                        for uid in range(numberOfUsers):
                            if online[uid]:
                                mentions[uid] += 1
                    else:  # idX
                        uid = int(token[2:])     # strip leading "id"
                        mentions[uid] += 1

        return mentions

