import math

class Solution:
    def assignElements(self, groups: List[int], elements: List[int]) -> List[int]:
        INF = 10 ** 9

        # determine the range of values we need to store
        max_val = 0
        if groups:
            max_val = max(max_val, max(groups))
        if elements:
            max_val = max(max_val, max(elements))

        # firstIdx[v] = smallest index of value v in elements, INF if absent
        firstIdx = [INF] * (max_val + 1)
        for idx, val in enumerate(elements):
            if idx < firstIdx[val]:
                firstIdx[val] = idx

        answer = []
        for g in groups:
            best = INF
            limit = int(math.isqrt(g))
            for d in range(1, limit + 1):
                if g % d == 0:
                    # divisor d
                    if d <= max_val and firstIdx[d] < best:
                        best = firstIdx[d]
                    # complementary divisor g//d
                    other = g // d
                    if other <= max_val and firstIdx[other] < best:
                        best = firstIdx[other]
            answer.append(best if best != INF else -1)

        return answer

