class Solution:
    def separateSquares(self, squares: List[List[int]]) -> float:
        # total area of all squares
        total_area = 0.0
        for _, _, l in squares:
            total_area += l * l
        target = total_area / 2.0

        # search interval
        low = min(y for _, y, _ in squares)
        high = max(y + l for _, y, l in squares)

        # binary search for height where area below = target
        for _ in range(80):          # sufficient for 1e-5 precision
            mid = (low + high) / 2.0
            below = 0.0
            for _, y, l in squares:
                if mid <= y:
                    continue                     # whole square above
                elif mid >= y + l:
                    below += l * l                # whole square below
                else:
                    below += l * (mid - y)        # partial area
            if below < target:
                low = mid
            else:
                high = mid

        return (low + high) / 2.0

