        # collect the best candidates from each row
        candidates = []
        for i, row in enumerate(grid):
            limit = limits[i]
            if limit <= 0:
                continue
            # sort row descending and take at most limit elements
            # row length is at most 500, sorting is fast enough
            top_vals = sorted(row, reverse=True)[:limit]
            candidates.extend(top_vals)

        # sort all candidates globally and take the largest k values
        candidates.sort(reverse=True)
        return sum(candidates[:k])

