class Solution:
    def minimumPairRemoval(self, nums: List[int]) -> int:
        # copy to avoid mutating input
        arr = nums[:]
        ops = 0

        def is_non_decreasing(a: List[int]) -> bool:
            for i in range(1, len(a)):
                if a[i] < a[i - 1]:
                    return False
            return True

        while not is_non_decreasing(arr):
            # find the adjacent pair with the minimum sum (leftmost on ties)
            min_sum = float('inf')
            idx = 0
            for i in range(len(arr) - 1):
                s = arr[i] + arr[i + 1]
                if s < min_sum:
                    min_sum = s
                    idx = i
            # replace the pair with their sum
            arr[idx] = arr[idx] + arr[idx + 1]
            del arr[idx + 1]
            ops += 1

        return ops

