class Solution:
    def maxProduct(self, nums: List[int], k: int, limit: int) -> int:
        # each state is a tuple (alternating_sum, product, parity)
        # parity = 0 -> next taken element will be added, 1 -> subtracted
        states = set()                     # reachable states so far
        for x in nums:
            new_states = set(states)        # option: skip x

            # start a new subsequence consisting only of x
            if x <= limit:
                new_states.add((x, x, 1))   # sum = x, product = x, length % 2 = 1

            # extend existing subsequences
            for s, prod, parity in states:
                new_sum = s + x if parity == 0 else s - x
                new_prod = prod * x
                if new_prod <= limit:
                    new_states.add((new_sum, new_prod, parity ^ 1))

            states = new_states

        best = -1
        for s, prod, _ in states:
            if s == k and prod > best:
                best = prod
        return best

