class Solution:
    def longestCommonPrefix(self, words: List[str], k: int) -> List[int]:
        n = len(words)
        answer = []
        for i in range(n):
            # Build the array after removing the i‑th element
            remaining = words[:i] + words[i + 1:]
            # If not enough strings remain, answer is 0
            if len(remaining) < k:
                answer.append(0)
                continue

            # Count how many strings share each possible prefix
            prefix_counts = {}
            for w in remaining:
                # generate all prefixes of the current word
                for l in range(1, len(w) + 1):
                    pref = w[:l]
                    prefix_counts[pref] = prefix_counts.get(pref, 0) + 1

            # Find the longest prefix that appears in at least k strings
            best_len = 0
            for pref, cnt in prefix_counts.items():
                if cnt >= k:
                    best_len = max(best_len, len(pref))

            answer.append(best_len)
        return answer

