        unplaced = 0

        for fruit in fruits:
            placed = False
            for i in range(n):
                if not used[i] and baskets[i] >= fruit:
                    used[i] = True   # occupy this basket
                    placed = True
                    break
            if not placed:
                unplaced += 1

        return unplaced

