class Solution:
    def numberOfComponents(self, properties: List[List[int]], k: int) -> int:
        n = len(properties)
        # distinct values of each row
        row_sets = [set(row) for row in properties]

        # Disjoint Set Union (Union-Find)
        parent = list(range(n))
        rank = [0] * n

        def find(x: int) -> int:
            while parent[x] != x:
                parent[x] = parent[parent[x]]   # path compression (halving)
                x = parent[x]
            return x

        def union(a: int, b: int) -> None:
            ra, rb = find(a), find(b)
            if ra == rb:
                return
            if rank[ra] < rank[rb]:
                parent[ra] = rb
            elif rank[ra] > rank[rb]:
                parent[rb] = ra
            else:
                parent[rb] = ra
                rank[ra] += 1

        # Build edges according to the condition
        for i in range(n):
            for j in range(i + 1, n):
                if len(row_sets[i] & row_sets[j]) >= k:
                    union(i, j)

        # Count distinct roots = connected components
        components = len({find(i) for i in range(n)})
        return components

