def count_up_to(N: int) -> int:
    if N < 10:
        return 0
    s = str(N)
    n = len(s)
    digits = list(map(int, s))
    total = 0

    # All snake numbers with length smaller than n
    for length in range(2, n):
        power = length - 1
        for lead in range(1, 10):
            total += pow(lead, power)

    # Numbers with length exactly n
    for lead in range(1, 10):
        if lead < digits[0]:
            total += pow(lead, n - 1)
        elif lead == digits[0]:
            @lru_cache(maxsize=None)
            def dfs(pos: int, tight: bool) -> int:
                if pos == n:
                    return 1
                limit = digits[pos] if tight else lead - 1
                cnt = 0
                for d in range(0, lead):
                    if d > limit:
                        break
                    cnt += dfs(pos + 1, tight and d == digits[pos])
                return cnt

            total += dfs(1, True)
        else:
            break  # larger leading digits would exceed N
    return total

