def fwht(a):
    n = len(a)
    step = 1
    while step < n:
        for i in range(0, n, step * 2):
            for j in range(step):
                x = a[i + j]
                y = a[i + j + step]
                a[i + j] = x + y
                a[i + j + step] = x - y
        step <<= 1

def ifwht(a):
