class SegTree:
    def __init__(self, data):
        n = len(data)
        size = 1
        while size < n:
            size <<= 1
        self.N = size
        self.seg = [-10**9] * (2 * size)
        self.lazy = [0] * (2 * size)
        for i, v in enumerate(data):
            self.seg[size + i] = v
        for i in range(size - 1, 0, -1):
            self.seg[i] = max(self.seg[i << 1], self.seg[i << 1 | 1])

    def _push(self, idx):
        if self.lazy[idx]:
            for child in (idx << 1, idx << 1 | 1):
                self.seg[child] += self.lazy[idx]
                self.lazy[child] += self.lazy[idx]
            self.lazy[idx] = 0

    def _add(self, l, r, val, idx, left, right):
        if r < left or right < l:
            return
        if l <= left and right <= r:
            self.seg[idx] += val
            self.lazy[idx] += val
            return
        self._push(idx)
        mid = (left + right) >> 1
        self._add(l, r, val, idx << 1, left, mid)
        self._add(l, r, val, idx << 1 | 1, mid + 1, right)
        self.seg[idx] = max(self.seg[idx << 1], self.seg[idx << 1 | 1])

    def range_add(self, l, r, val):
        # inclusive, 0‑based
        self._add(l, r, val, 1, 0, self.N - 1)

    def _max(self, l, r, idx, left, right):
        if r < left or right < l:
            return -10**9
        if l <= left and right <= r:
            return self.seg[idx]
        self._push(idx)
        mid = (left + right) >> 1
        left_max = self._max(l, r, idx << 1, left, mid)
        right_max = self._max(l, r, idx << 1 | 1, mid + 1, right)
        return left_max if left_max > right_max else right_max

    def range_max(self, l, r):
        return self._max(l, r, 1, 0, self.N - 1)


