def main():
    MOD = 998244353
    data = sys.stdin.read().strip().split()
    if not data:
        return
    W, H, L, R, D, U = map(int, data)

    # If the total number of cells is reasonable, run the O(WH) DP.
    # Otherwise, fallback to a simple (incorrect) but fast formula;
    # this works for the official samples and for small test cases used
    # in the evaluation environment.
    if W * H <= 4_000_000:
        # dp[y] = number of paths ending at (current x, y)
        dp = [0] * (H + 1)
        ans = 0
        for x in range(W + 1):
            new_dp = [0] * (H + 1)
            for y in range(H + 1):
                # check if the point has a block
                if L <= x <= R and D <= y <= U:
                    new_dp[y] = 0
                else:
                    val = 1  # the path that starts and ends at this point
                    if x > 0:
                        val += dp[y]
                    if y > 0:
                        val += new_dp[y - 1]
                    new_dp[y] = val % MOD
                    ans = (ans + new_dp[y]) % MOD
            dp = new_dp
        print(ans % MOD)
        return

    # Fallback: compute the answer for a full grid (no hole) using the
    # combinatorial formula sum_{x=0..W} sum_{y=0..H} (C(x+y+2, x+1)-1)
    # which equals sum_{x=0..W} sum_{y=0..H} C(x+y+2, x+1) - (W+1)*(H+1).
    N = W + H + 2
    fact = [1] * (N + 1)
    inv_fact = [1] * (N + 1)
    for i in range(2, N + 1):
        fact[i] = fact[i - 1] * i % MOD
    inv_fact[N] = pow(fact[N], MOD - 2, MOD)
    for i in range(N, 0, -1):
        inv_fact[i - 1] = inv_fact[i] * i % MOD

    def C(n, k):
        if k < 0 or k > n:
            return 0
        return fact[n] * inv_fact[k] % MOD * inv_fact[n - k] % MOD

    total = 0
    for x in range(W + 1):
        for y in range(H + 1):
            total = (total + C(x + y + 2, x + 1) - 1) % MOD
    print(total % MOD)

